// @ts-check
/**
 * Login script for one role of the test-auth kit. Generated by copying this
 * template verbatim with a single substitution (the role slug); run by the
 * operator at a terminal, never by an autonomous loop.
 *
 * Run order: the local-only guard, then the secrecy ensure, then reuse of a
 * valid session or a fresh login. Writes a Playwright storage-state file and,
 * when a token was read, a token artifact, both atomically and mode 0o600.
 * Prints statuses and repo-relative paths only, never a cookie, token,
 * password, username or response body.
 *
 * Usage:
 *   node PRPs/auth/login-<role>.mjs --plugin-root <dir> [--root <dir>] [--force]
 *   node PRPs/auth/login-<role>.mjs --help
 *
 * --plugin-root is mandatory (the CLAUDE_PLUGIN_ROOT environment variable is
 * the only alternative source); without either the script exits 2 without
 * writing. --root defaults to the current directory. An invalid role or an
 * unknown argument exits 2.
 *
 * Config: <root>/PRPs/auth/login.config.json
 *   { "baseUrl": string,
 *     "roles": { "<role>": {
 *       "mechanism": "form" | "api" | "headed" | "static-token",
 *       "loginPath": string | null,
 *       "form": { "usernameSelector", "passwordSelector", "submitSelector" } | null,
 *       "api": { "path", "method", "usernameField", "passwordField", "tokenPath": string | null } | null,
 *       "probe": { "path", "method" },
 *       "sessionCookie": string | null,
 *       "maxAgeMinutes": number,
 *       "credentials": { "usernameEnv": string | null, "passwordEnv": string | null },
 *       "userCreation": { "command": string[] | null },
 *       "needsIndexedDb": boolean (optional, default false),
 *       "staticToken": { "tokenEnv": string | null, "header": string, "valuePrefix": string,
 *         "browser": null | { "kind": "localStorage" | "indexedDB", "originPath": string,
 *           "key": string, "database": string | null, "store": string | null,
 *           "valueField": string | null } } } } }
 * The "static-token" mechanism sends no login request: the token comes from the
 * environment variable named by staticToken.tokenEnv, else the ignored
 * credentials store, else a terminal prompt; every staticToken field is
 * declared, never guessed. It is saved only after the protected probe answers
 * 2xx with the token and non-2xx without it.
 * A missing required field or a value equal to `TBD - needs validation`
 * halts FAILED_LOGIN_CONFIG_INCOMPLETE naming the field.
 *
 * Exit codes: 0 SESSION_REUSED or SESSION_CREATED, 1 a named FAILED_* halt,
 * 2 bad arguments.
 *
 * The consumer contract: the printed value `auth_mode: storage-state:<path>`
 * is handed to the visual capture unchanged.
 *
 * No npm dependencies of its own; `playwright` is resolved lazily at run time.
 * Node >=18, ESM.
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync, renameSync, statSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';

const ROLE = '__RELAY_ROLE__';
const ROLE_PATTERN = /^[a-z0-9][a-z0-9-]{0,39}$/;
const TBD = 'TBD - needs validation';
const SESSION_REL = `PRPs/auth/.sessions/${ROLE}.json`;
const TOKEN_REL = `PRPs/auth/.sessions/${ROLE}.token.json`;
const CREDENTIALS_REL = 'PRPs/auth/credentials.json';

const USAGE = `Usage:
  login-${ROLE}.mjs --plugin-root <dir> [--root <dir>] [--force]
  login-${ROLE}.mjs --help
`;

/**
 * @param {string[]} argv
 * @returns {{ help: boolean, force: boolean, root: string, pluginRoot: string | null } | null} null on bad arguments
 */
function parseArgs(argv) {
  let help = false;
  let force = false;
  let root = process.cwd();
  /** @type {string | null} */ let pluginRoot = null;
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--help') {
      help = true;
    } else if (a === '--force') {
      force = true;
    } else if (a === '--root' || a === '--plugin-root') {
      const v = argv[i + 1];
      if (v === undefined || v.startsWith('--')) return null;
      i++;
      if (a === '--root') root = resolve(v);
      else pluginRoot = resolve(v);
    } else {
      return null;
    }
  }
  if (!help && pluginRoot === null && process.env.CLAUDE_PLUGIN_ROOT) {
    pluginRoot = resolve(process.env.CLAUDE_PLUGIN_ROOT);
  }
  if (!help && pluginRoot === null) return null;
  return { help, force, root, pluginRoot };
}

/** @param {string} line */
function err(line) {
  process.stderr.write(`${line}\n`);
}

/**
 * @param {any} obj
 * @param {string} prefix
 * @returns {string | null} dotted path of the first TBD value
 */
function findTbd(obj, prefix) {
  if (obj === TBD) return prefix;
  if (obj && typeof obj === 'object') {
    for (const k of Object.keys(obj)) {
      const hit = findTbd(obj[k], `${prefix}.${k}`);
      if (hit) return hit;
    }
  }
  return null;
}

/**
 * @param {any} obj
 * @param {string} dotted
 * @returns {any}
 */
function getPath(obj, dotted) {
  let cur = obj;
  for (const k of dotted.split('.')) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    cur = cur[k];
  }
  return cur;
}

/**
 * @param {any} role
 * @returns {string | null} the first missing or TBD field, or null
 */
function incompleteField(role) {
  const tbd = findTbd(role, `roles.${ROLE}`);
  if (tbd) return tbd;
  /** @type {string[]} */
  let required = ['mechanism', 'probe.path', 'probe.method'];
  if (role.mechanism === 'form') {
    required = required.concat([
      'loginPath',
      'form.usernameSelector',
      'form.passwordSelector',
      'form.submitSelector',
    ]);
  } else if (role.mechanism === 'api') {
    required = required.concat(['api.path', 'api.method', 'api.usernameField', 'api.passwordField']);
  } else if (role.mechanism === 'headed') {
    required = required.concat(['loginPath']);
  } else if (role.mechanism === 'static-token') {
    required = required.concat(['staticToken.header']);
    const st = role.staticToken;
    if (!st || typeof st !== 'object' || typeof st.valuePrefix !== 'string') {
      return `roles.${ROLE}.staticToken.valuePrefix`;
    }
    if (st.browser === undefined) return `roles.${ROLE}.staticToken.browser`;
    if (st.browser !== null) {
      const kind = st.browser.kind;
      if (kind === 'localStorage') {
        required = required.concat(['staticToken.browser.originPath', 'staticToken.browser.key']);
      } else if (kind === 'indexedDB') {
        required = required.concat([
          'staticToken.browser.originPath',
          'staticToken.browser.key',
          'staticToken.browser.database',
          'staticToken.browser.store',
        ]);
      } else {
        return `roles.${ROLE}.staticToken.browser.kind`;
      }
    }
  } else {
    return `roles.${ROLE}.mechanism`;
  }
  for (const f of required) {
    const v = getPath(role, f);
    if (typeof v !== 'string' || v === '') return `roles.${ROLE}.${f}`;
  }
  if (typeof role.maxAgeMinutes !== 'number' || !(role.maxAgeMinutes > 0)) {
    return `roles.${ROLE}.maxAgeMinutes`;
  }
  return null;
}

/**
 * Prompt on stderr; the typed value is never echoed when `echo` is false.
 * @param {string} promptText
 * @param {boolean} echo
 * @returns {Promise<string>}
 */
function readLine(promptText, echo) {
  return new Promise((done) => {
    process.stderr.write(promptText);
    const stdin = process.stdin;
    let buf = '';
    stdin.setRawMode(true);
    stdin.resume();
    stdin.setEncoding('utf8');
    const cleanup = () => {
      stdin.removeListener('data', onData);
      stdin.setRawMode(false);
      stdin.pause();
    };
    /** @param {string} chunk */
    const onData = (chunk) => {
      for (const ch of chunk) {
        if (ch === '\r' || ch === '\n') {
          cleanup();
          process.stderr.write('\n');
          done(buf);
          return;
        }
        if (ch === '\u0003') {
          cleanup();
          process.stderr.write('\n');
          process.exit(1);
        }
        if (ch === '\u007f' || ch === '\b') {
          buf = buf.slice(0, -1);
          continue;
        }
        buf += ch;
        if (echo) process.stderr.write(ch);
      }
    };
    stdin.on('data', onData);
  });
}

/**
 * @param {string} root
 * @param {string} rel
 * @returns {any | null}
 */
function readJson(root, rel) {
  try {
    return JSON.parse(readFileSync(join(root, rel), 'utf8'));
  } catch {
    return null;
  }
}

/**
 * Resolve credentials from the named environment variables, then the
 * git-ignored credentials file.
 * @param {string} root
 * @param {any} role
 * @returns {{ username: string, password: string } | null}
 */
function resolveCredentials(root, role) {
  const c = role.credentials || {};
  if (c.usernameEnv && c.passwordEnv) {
    const u = process.env[c.usernameEnv];
    const p = process.env[c.passwordEnv];
    if (u && p) return { username: u, password: p };
  }
  const file = readJson(root, CREDENTIALS_REL);
  const entry = file && typeof file === 'object' ? file[ROLE] : null;
  if (entry && typeof entry.username === 'string' && typeof entry.password === 'string') {
    if (entry.username !== '' && entry.password !== '') {
      return { username: entry.username, password: entry.password };
    }
  }
  return null;
}

/**
 * @param {string} root
 * @param {string} pluginRoot
 * @returns {any | null}
 */
function loadPlaywright(root, pluginRoot) {
  for (const base of [join(root, 'package.json'), join(pluginRoot, 'scripts', 'visual', 'package.json')]) {
    try {
      const mod = createRequire(base)('playwright');
      pwBase = base;
      return mod;
    } catch {
      // try the next resolution root
    }
  }
  return null;
}

/** The package.json base that resolved Playwright (null until it resolves). @type {string | null} */
let pwBase = null;

/**
 * @returns {string | null} the resolved Playwright version, or null when unreadable
 */
function playwrightVersion() {
  if (pwBase === null) return null;
  try {
    const v = createRequire(pwBase)('playwright/package.json').version;
    return typeof v === 'string' ? v : null;
  } catch {
    return null;
  }
}

/**
 * IndexedDB capture needs Playwright >= 1.51; an unreadable version is
 * unsupported (fail closed).
 * @returns {boolean}
 */
function indexedDbSupported() {
  const v = playwrightVersion();
  if (v === null) return false;
  const m = /^(\d+)\.(\d+)/.exec(v);
  if (!m) return false;
  const major = Number(m[1]);
  const minor = Number(m[2]);
  return major > 1 || (major === 1 && minor >= 51);
}

/**
 * @param {any} role
 * @returns {boolean} true when the role's session must carry IndexedDB
 */
function needsIndexedDb(role) {
  if (role.needsIndexedDb === true) return true;
  return (
    role.mechanism === 'static-token' &&
    !!role.staticToken &&
    !!role.staticToken.browser &&
    role.staticToken.browser.kind === 'indexedDB'
  );
}

/**
 * @param {string} token
 * @returns {number | null} exp in epoch seconds when the token is a JWT with an exp claim
 */
function jwtExp(token) {
  const parts = String(token).split('.');
  if (parts.length !== 3) return null;
  try {
    const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    return typeof payload.exp === 'number' ? payload.exp : null;
  } catch {
    return null;
  }
}

/**
 * @param {string} baseUrl
 * @param {string} p
 * @returns {string | null} absolute URL on the same origin, or null
 */
function sameOriginUrl(baseUrl, p) {
  try {
    const base = new URL(baseUrl);
    const u = new URL(p, base);
    return u.origin === base.origin ? u.href : null;
  } catch {
    return null;
  }
}

/**
 * Static checks on an existing session file, then a probe request.
 * @param {string} root
 * @param {any} cfg
 * @param {any} role
 * @param {() => any} getPlaywright
 * @returns {Promise<boolean>}
 */
async function sessionReusable(root, cfg, role, getPlaywright) {
  const file = join(root, SESSION_REL);
  if (!existsSync(file)) return false;
  const state = readJson(root, SESSION_REL);
  if (!state || !Array.isArray(state.cookies) || !Array.isArray(state.origins)) return false;
  if (Date.now() - statSync(file).mtimeMs >= role.maxAgeMinutes * 60000) return false;
  if (role.sessionCookie) {
    const nowSec = Date.now() / 1000;
    const hit = state.cookies.find(
      (/** @type {any} */ c) => c.name === role.sessionCookie && (c.expires === -1 || c.expires > nowSec + 60),
    );
    if (!hit) return false;
  }
  const url = sameOriginUrl(cfg.baseUrl, role.probe.path);
  if (!url) return false;
  const pw = getPlaywright();
  if (!pw) return false;
  const ctx = await pw.request.newContext({ storageState: file });
  try {
    const res = await ctx.fetch(url, { method: role.probe.method, maxRedirects: 0 });
    return res.status() >= 200 && res.status() < 300;
  } catch {
    return false;
  } finally {
    await ctx.dispose();
  }
}

/**
 * @param {any} cfg
 * @param {any} role
 * @param {{ username: string, password: string }} creds
 * @param {any} pw
 * @returns {Promise<{ state: any, token: string | null } | null>}
 */
async function loginApi(cfg, role, creds, pw) {
  const url = sameOriginUrl(cfg.baseUrl, role.api.path);
  if (!url) return null;
  const ctx = await pw.request.newContext({ baseURL: cfg.baseUrl });
  try {
    const res = await ctx.fetch(url, {
      method: role.api.method,
      data: { [role.api.usernameField]: creds.username, [role.api.passwordField]: creds.password },
      maxRedirects: 0,
    });
    if (res.status() < 200 || res.status() >= 300) return null;
    /** @type {string | null} */ let token = null;
    if (role.api.tokenPath) {
      try {
        const v = getPath(await res.json(), role.api.tokenPath);
        if (typeof v === 'string' && v !== '') token = v;
      } catch {
        token = null;
      }
      if (token === null) return null;
    }
    const state = await ctx.storageState({ indexedDB: true });
    return { state, token };
  } catch {
    return null;
  } finally {
    await ctx.dispose();
  }
}

/**
 * @param {any} cfg
 * @param {any} role
 * @param {{ username: string, password: string }} creds
 * @param {any} pw
 * @param {{ checkTarget: Function, isAllowedHost: Function }} guard
 * @param {string} root
 * @param {Set<string>} allowedHosts
 * @returns {Promise<any | null>}
 */
async function loginForm(cfg, role, creds, pw, guard, root, allowedHosts) {
  const browser = await pw.chromium.launch({ headless: true });
  try {
    const context = await browser.newContext();
    await context.route('**/*', (/** @type {any} */ route) => {
      const u = new URL(route.request().url());
      if (['data:', 'about:', 'blob:'].includes(u.protocol)) return route.continue();
      return guard.isAllowedHost(u.hostname, allowedHosts) ? route.continue() : route.abort();
    });
    const page = await context.newPage();
    const loginUrl = sameOriginUrl(cfg.baseUrl, role.loginPath);
    if (!loginUrl) return null;
    await page.goto(loginUrl);
    await page.fill(role.form.usernameSelector, creds.username);
    await page.fill(role.form.passwordSelector, creds.password);
    await page.click(role.form.submitSelector);
    await page.waitForURL(
      (/** @type {URL} */ u) => u.pathname !== new URL(loginUrl).pathname,
      { timeout: 15000 },
    );
    const final = await guard.checkTarget(page.url(), { root });
    if (!final.ok) return null;
    return await context.storageState({ indexedDB: true });
  } catch {
    return null;
  } finally {
    await browser.close();
  }
}

/**
 * @param {any} cfg
 * @param {any} role
 * @param {any} pw
 * @param {{ checkTarget: Function }} guard
 * @param {string} root
 * @returns {Promise<{ state: any | null, nonLocal: boolean }>}
 */
async function loginHeaded(cfg, role, pw, guard, root) {
  const browser = await pw.chromium.launch({ headless: false });
  try {
    const context = await browser.newContext();
    const page = await context.newPage();
    const loginUrl = sameOriginUrl(cfg.baseUrl, role.loginPath);
    if (!loginUrl) return { state: null, nonLocal: false };
    await page.goto(loginUrl);
    await readLine('Complete the login in the browser, then press Enter here', true);
    const final = await guard.checkTarget(page.url(), { root });
    if (!final.ok) return { state: null, nonLocal: true };
    return { state: await context.storageState({ indexedDB: true }), nonLocal: false };
  } catch {
    return { state: null, nonLocal: false };
  } finally {
    await browser.close();
  }
}

/**
 * Token source for a static-token role: the environment variable NAMED by
 * staticToken.tokenEnv, else the ignored credentials store, else a terminal
 * prompt (never echoed, held in memory only). The caller persists a prompted
 * token only after the proof and the browser step succeed.
 * @param {string} root
 * @param {any} role
 * @returns {Promise<{ token: string, prompted: boolean } | null>}
 */
async function resolveStaticToken(root, role) {
  const st = role.staticToken || {};
  if (typeof st.tokenEnv === 'string' && st.tokenEnv !== '') {
    const v = process.env[st.tokenEnv];
    if (v) return { token: v, prompted: false };
  }
  const file = readJson(root, CREDENTIALS_REL);
  const entry = file && typeof file === 'object' ? file[ROLE] : null;
  if (entry && typeof entry.token === 'string' && entry.token !== '') {
    return { token: entry.token, prompted: false };
  }
  if (process.stdin.isTTY) {
    const typed = await readLine(`Token for role ${ROLE} (not echoed): `, false);
    if (typed !== '') return { token: typed, prompted: true };
  }
  return null;
}

/**
 * Confirm the token against the protected probe endpoint: 2xx with the
 * declared header and non-2xx without it.
 * @param {any} cfg
 * @param {any} role
 * @param {string} token
 * @param {any} pw
 * @returns {Promise<'proven' | 'unproven' | 'rejected'>}
 */
async function proveStaticToken(cfg, role, token, pw) {
  const url = sameOriginUrl(cfg.baseUrl, role.probe.path);
  if (!url) return 'rejected';
  /**
   * @param {Record<string, string> | undefined} headers
   * @returns {Promise<number>}
   */
  const status = async (headers) => {
    const ctx = await pw.request.newContext();
    try {
      const res = await ctx.fetch(url, { method: role.probe.method, headers, maxRedirects: 0 });
      return res.status();
    } finally {
      await ctx.dispose();
    }
  };
  try {
    const withToken = await status({ [role.staticToken.header]: `${role.staticToken.valuePrefix}${token}` });
    if (withToken < 200 || withToken >= 300) return 'rejected';
    const without = await status(undefined);
    return without >= 200 && without < 300 ? 'unproven' : 'proven';
  } catch {
    return 'rejected';
  }
}

/**
 * Static checks on an existing static-token session, then the with/without
 * proof using the token read from the ignored token artifact (never printed).
 * @param {string} root
 * @param {any} cfg
 * @param {any} role
 * @param {() => any} getPlaywright
 * @returns {Promise<boolean>}
 */
async function staticTokenReusable(root, cfg, role, getPlaywright) {
  const file = join(root, SESSION_REL);
  if (!existsSync(file)) return false;
  const state = readJson(root, SESSION_REL);
  if (!state || !Array.isArray(state.cookies) || !Array.isArray(state.origins)) return false;
  if (Date.now() - statSync(file).mtimeMs >= role.maxAgeMinutes * 60000) return false;
  const art = readJson(root, TOKEN_REL);
  if (!art || typeof art.token !== 'string' || art.token === '') return false;
  const pw = getPlaywright();
  if (!pw) return false;
  return (await proveStaticToken(cfg, role, art.token, pw)) === 'proven';
}

/**
 * Put the token at the declared browser location and capture the storage
 * state (IndexedDB included). The location is declared, never guessed.
 * @param {any} cfg
 * @param {any} role
 * @param {string} token
 * @param {any} pw
 * @param {{ checkTarget: Function, isAllowedHost: Function }} guard
 * @param {string} root
 * @param {Set<string>} allowedHosts
 * @returns {Promise<{ state: any | null, halt: string | null }>}
 */
async function placeStaticToken(cfg, role, token, pw, guard, root, allowedHosts) {
  const loc = role.staticToken.browser;
  const unreachable = (/** @type {string} */ what) => ({
    state: null,
    halt: `FAILED_TOKEN_LOCATION_UNREACHABLE: ${what}; nothing was saved`,
  });
  const browser = await pw.chromium.launch({ headless: true });
  try {
    const context = await browser.newContext();
    await context.route('**/*', (/** @type {any} */ route) => {
      const u = new URL(route.request().url());
      if (['data:', 'about:', 'blob:'].includes(u.protocol)) return route.continue();
      return guard.isAllowedHost(u.hostname, allowedHosts) ? route.continue() : route.abort();
    });
    const page = await context.newPage();
    const appUrl = sameOriginUrl(cfg.baseUrl, loc.originPath);
    if (!appUrl) return { state: null, halt: `FAILED_LOGIN_REJECTED: the login for role ${ROLE} yielded no session` };
    await page.goto(appUrl);
    const final = await guard.checkTarget(page.url(), { root });
    if (!final.ok) return { state: null, halt: 'FAILED_NON_LOCAL_TARGET: final-page (nothing was saved)' };
    if (loc.kind === 'localStorage') {
      await page.evaluate((/** @type {{ key: string, token: string }} */ a) => localStorage.setItem(a.key, a.token), {
        key: loc.key,
        token,
      });
    } else {
      // Poll from Node: page.evaluate awaits a promise, whereas waitForFunction does not
      // await an async predicate (the Promise object is truthy and it resolves at once).
      const dbDeadline = Date.now() + 10000;
      let dbAppeared = false;
      while (!dbAppeared) {
        try {
          dbAppeared = await page.evaluate(
            async (/** @type {string} */ db) => (await indexedDB.databases()).some((d) => d.name === db),
            loc.database,
          );
        } catch {
          dbAppeared = false;
        }
        if (dbAppeared) break;
        if (Date.now() >= dbDeadline) {
          return unreachable(`IndexedDB database ${loc.database} did not appear on ${loc.originPath}`);
        }
        await new Promise((r) => setTimeout(r, 250));
      }
      const outcome = await page.evaluate(
        async (/** @type {{ db: string, store: string, key: string, valueField: string | null, token: string }} */ a) => {
          /** @type {IDBDatabase} */
          let conn;
          try {
            conn = await new Promise((ok, bad) => {
              const r = indexedDB.open(a.db);
              r.onupgradeneeded = () => r.transaction && r.transaction.abort();
              r.onsuccess = () => ok(r.result);
              r.onerror = () => bad(r.error);
            });
          } catch {
            return 'no-database';
          }
          try {
            if (!conn.objectStoreNames.contains(a.store)) return 'no-store';
            const tx = conn.transaction(a.store, 'readwrite');
            const os = tx.objectStore(a.store);
            const kp = os.keyPath;
            const done = new Promise((ok, bad) => {
              tx.oncomplete = () => ok(true);
              tx.onerror = () => bad(tx.error);
              tx.onabort = () => bad(tx.error);
            });
            if (kp === null) {
              os.put(a.token, a.key);
            } else if (typeof kp === 'string' && a.valueField) {
              os.put({ [kp]: a.key, [a.valueField]: a.token });
            } else {
              tx.abort();
              return typeof kp === 'string' ? 'need-value-field' : 'no-store';
            }
            await done;
            return 'ok';
          } catch {
            return 'no-store';
          } finally {
            conn.close();
          }
        },
        { db: loc.database, store: loc.store, key: loc.key, valueField: loc.valueField || null, token },
      );
      if (outcome === 'need-value-field') {
        return { state: null, halt: `FAILED_LOGIN_CONFIG_INCOMPLETE: roles.${ROLE}.staticToken.browser.valueField` };
      }
      if (outcome !== 'ok') {
        return unreachable(`IndexedDB database ${loc.database} or object store ${loc.store} is not usable`);
      }
    }
    return { state: await context.storageState({ indexedDB: true }), halt: null };
  } catch {
    return { state: null, halt: `FAILED_LOGIN_REJECTED: the login for role ${ROLE} yielded no session` };
  } finally {
    await browser.close();
  }
}

/**
 * @param {string[]} argv
 * @returns {Promise<number>} exit code
 */
async function main(argv) {
  const args = parseArgs(argv);
  if (args === null) {
    process.stderr.write(USAGE);
    return 2;
  }
  if (args.help) {
    process.stdout.write(USAGE);
    return 0;
  }
  if (!ROLE_PATTERN.test(ROLE)) {
    process.stderr.write(USAGE);
    return 2;
  }
  const root = args.root;
  const pluginRoot = /** @type {string} */ (args.pluginRoot);

  const cfg = readJson(root, 'PRPs/auth/login.config.json');
  if (!cfg || typeof cfg.baseUrl !== 'string' || cfg.baseUrl === '' || cfg.baseUrl === TBD) {
    err('FAILED_LOGIN_CONFIG_INCOMPLETE: baseUrl');
    return 1;
  }

  // GUARD-SITE
  /** @type {any} */ let guard;
  try {
    guard = await import(pathToFileURL(join(pluginRoot, 'scripts', 'auth-local-guard.mjs')).href);
    if (typeof guard.checkTarget !== 'function' || typeof guard.isAllowedHost !== 'function') {
      throw new Error('guard export missing');
    }
  } catch {
    err('FAILED_GUARD_UNAVAILABLE: the local-only guard script could not be loaded; refusing to continue (fail closed)');
    return 1;
  }
  const target = await guard.checkTarget(cfg.baseUrl, { root });
  if (!target.ok) {
    err(`FAILED_NON_LOCAL_TARGET: ${target.reason} (host: ${target.host})`);
    return 1;
  }

  // SECRECY-SITE
  const secrecy = spawnSync(
    process.execPath,
    [
      join(pluginRoot, 'scripts', 'auth-kit-secrecy.mjs'),
      'ensure',
      '--root',
      root,
      '--path',
      CREDENTIALS_REL,
      '--path',
      SESSION_REL,
      '--path',
      TOKEN_REL,
    ],
    { encoding: 'utf8' },
  );
  if (secrecy.error || secrecy.status !== 0) {
    const msg = String(secrecy.stderr || '').trim();
    err(msg.includes('FAILED_IGNORE_UNPROVEN') ? msg : 'FAILED_IGNORE_UNPROVEN: the secrecy script could not prove the ignore rules');
    return 1;
  }

  const role = cfg.roles && cfg.roles[ROLE];
  if (!role || typeof role !== 'object') {
    err(`FAILED_LOGIN_CONFIG_INCOMPLETE: roles.${ROLE}`);
    return 1;
  }
  const missing = incompleteField(role);
  if (missing) {
    err(`FAILED_LOGIN_CONFIG_INCOMPLETE: ${missing}`);
    return 1;
  }

  /** @type {any} */ let pw = null;
  let pwTried = false;
  const getPlaywright = () => {
    if (!pwTried) {
      pwTried = true;
      pw = loadPlaywright(root, pluginRoot);
    }
    return pw;
  };
  const requirePlaywright = () => {
    const p = getPlaywright();
    if (!p) {
      err('FAILED_PLAYWRIGHT_UNAVAILABLE: playwright is not resolvable; run `npm install` in plugins/relay/scripts/visual/');
      return p;
    }
    if (needsIndexedDb(role) && !indexedDbSupported()) {
      err('FAILED_INDEXEDDB_UNSUPPORTED: the resolved Playwright cannot capture IndexedDB (needs >= 1.51); nothing was saved');
      return null;
    }
    return p;
  };

  const reusable =
    !args.force &&
    (role.mechanism === 'static-token'
      ? await staticTokenReusable(root, cfg, role, getPlaywright)
      : await sessionReusable(root, cfg, role, getPlaywright));
  if (reusable) {
    process.stdout.write(`SESSION_REUSED: ${SESSION_REL}\n`);
    process.stdout.write(`auth_mode: storage-state:${SESSION_REL}\n`);
    return 0;
  }

  /** @type {any | null} */ let state = null;
  /** @type {string | null} */ let token = null;
  let promptedToken = false;

  if (role.mechanism === 'headed') {
    if (!process.stdin.isTTY) {
      err('FAILED_INTERACTIVE_LOGIN_REQUIRED: a headed login needs a terminal; run this script at your own terminal');
      return 1;
    }
    if (!requirePlaywright()) return 1;
    const r = await loginHeaded(cfg, role, pw, guard, root);
    if (r.nonLocal) {
      err('FAILED_NON_LOCAL_TARGET: final-page (nothing was saved)');
      return 1;
    }
    state = r.state;
  } else if (role.mechanism === 'static-token') {
    if (!requirePlaywright()) return 1;
    const source = await resolveStaticToken(root, role);
    if (!source) {
      err(`FAILED_CREDENTIALS_UNAVAILABLE: no token source for role ${ROLE} (environment variable, credentials file, terminal)`);
      return 1;
    }
    const proof = await proveStaticToken(cfg, role, source.token, pw);
    if (proof === 'unproven') {
      err('FAILED_TOKEN_UNPROVEN: the protected endpoint answered 2xx with and without the token; no session was saved');
      return 1;
    }
    if (proof !== 'proven') {
      err(`FAILED_LOGIN_REJECTED: the login for role ${ROLE} yielded no session`);
      return 1;
    }
    if (role.staticToken.browser === null) {
      state = { cookies: [], origins: [] };
    } else {
      const placed = await placeStaticToken(cfg, role, source.token, pw, guard, root, target.allowedHosts);
      if (placed.halt) {
        err(placed.halt);
        return 1;
      }
      state = placed.state;
    }
    token = source.token;
    promptedToken = source.prompted;
  } else {
    let creds = resolveCredentials(root, role);
    if (!creds && role.userCreation && Array.isArray(role.userCreation.command) && role.userCreation.command.length > 0) {
      const [cmd, ...cmdArgs] = role.userCreation.command;
      spawnSync(cmd, cmdArgs, { shell: false, stdio: 'ignore', cwd: root });
      creds = resolveCredentials(root, role);
    }
    if (!creds && process.stdin.isTTY) {
      const username = await readLine(`Username for role ${ROLE}: `, true);
      const password = await readLine(`Password for role ${ROLE} (not echoed): `, false);
      if (username !== '' && password !== '') {
        creds = { username, password };
        const existing = readJson(root, CREDENTIALS_REL);
        const merged = existing && typeof existing === 'object' ? existing : {};
        merged[ROLE] = creds;
        writeSecret(root, CREDENTIALS_REL, `${JSON.stringify(merged, null, 2)}\n`);
      }
    }
    if (!creds) {
      err(`FAILED_CREDENTIALS_UNAVAILABLE: no credential source for role ${ROLE} (environment variables, credentials file, user-creation command, terminal)`);
      return 1;
    }
    if (!requirePlaywright()) return 1;
    if (role.mechanism === 'api') {
      const r = await loginApi(cfg, role, creds, pw);
      if (r) {
        state = r.state;
        token = r.token;
      }
    } else {
      state = await loginForm(cfg, role, creds, pw, guard, root, target.allowedHosts);
    }
  }

  const hasCookies = state && Array.isArray(state.cookies) && state.cookies.length > 0;
  if (!state || !Array.isArray(state.cookies) || !Array.isArray(state.origins) || (!hasCookies && token === null)) {
    err(`FAILED_LOGIN_REJECTED: the login for role ${ROLE} yielded no session`);
    return 1;
  }
  if (role.sessionCookie && !state.cookies.some((/** @type {any} */ c) => c.name === role.sessionCookie)) {
    err(`FAILED_LOGIN_REJECTED: the login for role ${ROLE} yielded no session`);
    return 1;
  }

  if (promptedToken && token !== null) {
    const existing = readJson(root, CREDENTIALS_REL);
    const merged = existing && typeof existing === 'object' ? existing : {};
    merged[ROLE] = { token };
    writeSecret(root, CREDENTIALS_REL, `${JSON.stringify(merged, null, 2)}\n`);
  }
  writeSecret(root, SESSION_REL, `${JSON.stringify(state, null, 2)}\n`);
  if (token !== null) {
    const exp = jwtExp(token);
    const expiresAt = exp !== null ? new Date(exp * 1000) : new Date(Date.now() + role.maxAgeMinutes * 60000);
    /** @type {Record<string, string>} */
    const artifact = { token, expires_at: expiresAt.toISOString(), obtained_at: new Date().toISOString() };
    if (role.mechanism === 'static-token') {
      artifact.header = role.staticToken.header;
      artifact.value_prefix = role.staticToken.valuePrefix;
    }
    writeSecret(root, TOKEN_REL, `${JSON.stringify(artifact, null, 2)}\n`);
  }
  process.stdout.write(`SESSION_CREATED: ${SESSION_REL}\n`);
  process.stdout.write(`auth_mode: storage-state:${SESSION_REL}\n`);
  return 0;
}

// WRITE-SITE
/**
 * The only place a secret file is written: tmp-then-rename, mode 0o600,
 * parent directory created first.
 * @param {string} root
 * @param {string} rel repo-relative path
 * @param {string} content
 */
function writeSecret(root, rel, content) {
  const dest = join(root, rel);
  mkdirSync(join(dest, '..'), { recursive: true });
  const tmp = `${dest}.tmp`;
  writeFileSync(tmp, content, { encoding: 'utf8', mode: 0o600 });
  renameSync(tmp, dest);
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  process.exitCode = await main(process.argv.slice(2));
}
